a={e['section']:e for e in es if e.get('kind')=='answer' and e.get('section','').startswith('question:') and e['seq'] not in superseded}
out={}
for k,e in sorted(a.items(),key=lambda kv:int(kv[0].split(':')[1])):
 reviews=[r for r in rs if r.get('seq')==e['seq'] and r.get('target')==e.get('hash') and r.get('by')!=e.get('by')]
 disputes=[d for d in ds if d.get('seq')==e['seq']]
 row={'entry':'E-'+str(e['seq']),'result':e.get('result'),'author':e.get('by'),'reviews':[{'reviewer':r.get('by'),'strength':r.get('strength')} for r in reviews],'dispute_rows':len(disputes),'support':['E-'+str(s['seq']) for s in e.get('support',[])]}
 if args.get('include_values',False):row['answer']=e['value']
 out[k]=row
print(json.dumps({'warning':'Register state only; freshness, coverage, disputes and evidence must be independently checked before final publication.','sections':out},indent=2))
